    ["270cb3d"] = "Für deine Spezialisierung ist das am wichtigsten.",
    ["759646f"] = "DPS der Nahkampfwaffe:",
    ["620e128"] = "aber deine Spezialisierung kämpft nicht mit dieser Waffe und nutzt sie nicht.",
    ["f8fc3c4"] = "was für deine Spezialisierung zählt.",
    ["4842b23"] = "Die anderen Unterschiede (Rüstung, Schaden...) zählen für deine Spezialisierung nicht.",
    ["46e81de"] = "Die Werte, die für dich zählen, sind gleich.",
    ["984170a"] = "Für deine Spezialisierung zählt in diesem Platz vor allem: %s.",
    ["8878fa5"] = "Die Beast-Mastery-Rotation der Anleitung (Leveln 1-60): kein Nahkampf; Hunter's Mark und Serpent Sting als Eröffnung, Falken (Summon Hawk) ab 25, Aimed Shot und Arcane Shot, Multi-Shot und Explosive Trap gegen mehrere Monster. Fähigkeiten mit langer Abklingzeit (Bestial Wrath, Rapid Fire, Volksfähigkeiten) bleiben außerhalb der Rotation und werden von Hand eingesetzt. Erstellt von BuildBeast.",
    ["f7219d4"] = "für diese Spezialisierung hat BuildBeast noch keine eigene Rotation: Hekili nutzt seine eigene.",
    ["f23ecca"] = "Hekili ist nicht geladen.",
    ["2ec553f"] = "Ich konnte die Priorität in Hekili nicht erstellen.",
    ["9e1f59d"] = "Hekili nutzt bereits die Priorität: %s",
    ["bbf6862"] = "Hekili-Priorität gesetzt: %s",
    ["3f1c97f"] = "Hekili hat die Priorität nicht akzeptiert.",
    ["511ff29"] = "Leuchten der Tasten:",
    ["c172ef4"] = "an",
    ["72960be"] = "aus",
    ["969f47a"] = "Gold = jetzt benutzen, Blau = die nächste.",
    ["2850cfb"] = "Abklingzeit-Schattierung:",
    ["c4ad91d"] = "sichtbar",
    ["aba8815"] = "versteckt",
    ["babe955"] = "Abklingzeit-Zahlen auf den Tasten:",
    ["48983fc"] = "an",
    ["3424735"] = "aus",
    ["8b823dc"] = "Zygor ist nicht bereit.",
    ["7496082"] = "Zygor-Talentmarkierungen:",
    ["1b9f260"] = "Öffne das Talentfenster erneut.",
    ["7c4161e"] = "Du wechselst das Ziel, ohne Auto Shot zu unterbrechen.",
    ["3ddfa3b"] = "Das Tier greift das Ziel an, das du mit Hunter's Mark markierst.",
    ["d00e00c"] = "Eine Taste für die Nahkampffähigkeiten, wenn du angegriffen wirst.",
    ["458bcf6"] = "Wechselt Mongoose Bite und Counterattack auf einer Taste ab, nach einem Ausweichen oder Parieren.",
    ["7e3322d"] = "Wirkt die Fähigkeit und startet den automatischen Angriff, auch schon vor dem Kampfbeginn. Statt Heroic Strike kannst du eine andere Fähigkeit einsetzen. Es braucht genug Wut.",
    ["4215a24"] = "Sunder Armor auf den Gegner unter dem Cursor, ohne ihn anzuvisieren.",
    ["fade647"] = "Blessing of Protection auf den Verbündeten unter dem Cursor (falls keiner da ist, auf dein Ziel).",
    ["0ea3265"] = "Blessing of Freedom auf den Verbündeten unter dem Cursor.",
    ["474ed6a"] = "Cleanse auf den Verbündeten unter dem Cursor.",
    ["dd398c9"] = "Beschwört die Advanced Target Dummy am Cursor und wirkt Blessing of Protection darauf: zweimal drücken, ohne aktive globale Abklingzeit.",
    ["ad171ca"] = "Divine Shield auf dich; erneutes Drücken entfernt es sofort. Zweimal drücken, ohne aktive globale Abklingzeit.",
    ["8b1f0a2"] = "Startet den automatischen Angriff und wirkt Holy Strike. Nicht auf Holy Shield legen.",
    ["39da0a5"] = "Power Word: Shield auf den Cursor, sonst auf dich.",
    ["885b4fd"] = "Greater Heal auf den Cursor, sonst auf das Ziel, sonst auf dich.",
    ["f6044e4"] = "Bricht den laufenden Zauber ab und wirkt Greater Heal neu: für den Fall, dass ein anderer Heiler das Ziel schon geheilt hat.",
    ["73afb8f"] = "Inner Focus und sofort Prayer of Healing: für Notfälle.",
    ["91996ef"] = "Schlaues Dispel Magic: entfernt schädliche Magie von Verbündeten und nützliche von Feinden.",
    ["b32d1df"] = "Prayer of Mending auf den Cursor, sonst auf das Ziel, sonst auf dich.",
    ["4e5454e"] = "Bricht den Zauber ab und nutzt Shadow Word: Death auf ein fast totes Monster, das flieht, oder auf ein Totem.",
    ["4b2ea52"] = "Trägt Deadly Poison auf die Waffe der Haupthand auf; das Symbol zeigt die Dauer.",
    ["73d1f2d"] = "Trägt Instant Poison auf die Waffe der Nebenhand auf; das Symbol zeigt die Dauer.",
    ["672d6cc"] = "Pick Pocket als Eröffnung, dann Garrote (du kannst es durch Cheap Shot oder Ambush ersetzen).",
    ["c2da64b"] = "Schickt Tier und Charakter mit einer Taste in den Angriff: So stehst du beim Leveln nicht still.",
    ["6252d01"] = "Wie GL Attacco, wirkt aber zusätzlich Stormstrike (statt des vorherigen Makros).",
    ["79e760c"] = "Totemic Projection dorthin, wo der Cursor ist.",
    ["93ec012"] = "Nature's Swiftness und sofort Healing Wave auf den Cursor: sofortige Notfallheilung. Entferne [@mouseover], wenn du die Heilung per Cursor nicht willst.",
    ["ddfe74e"] = "Polymorph auf das Fokusziel; wenn keines da ist oder es kein Feind ist, auf das aktuelle Ziel.",
    ["425c144"] = "Nutzt beide Schmuckstücke mit einer Taste (Plätze 13 und 14).",
    ["23fc3c4"] = "Combustion zusammen mit beiden Schmuckstücken.",
    ["6d5d784"] = "Schickt das Tier in den Angriff und stellt es dann auf passiv, wie in der Anleitung.",
    ["3b9d855"] = "Amplify Curse und Bane of Agony zusammen: für die Eröffnung oder wenn Amplify Curse bereit ist.",
    ["67eb4db"] = "Drain Life, das du mehrmals drücken kannst, ohne es zu unterbrechen.",
    ["c24583f"] = "Corruption auf das Ziel unter dem Cursor: um mehrere Feinde mit DOTs zu belegen. Ersetze Corruption durch einen anderen DOT.",
    ["de046d0"] = "Fel Domination und sofort Imp: um das Tier nach seinem Tod zurückzurufen oder für den Execute-Build.",
    ["0da2d35"] = "Fel Domination und sofort Succubus: um das Tier nach seinem Tod zurückzurufen.",
    ["701f8c9"] = "Bane of Havoc auf das Ziel unter dem Cursor.",
    ["6177927"] = "Immolate auf den Fokus (das Ziel von Bane of Havoc).",
    ["687eb32"] = "Corruption auf den Fokus.",
    ["dfc9982"] = "Bane of Doom auf den Fokus.",
    ["f14c9c9"] = "Bane of Agony auf den Fokus.",
    ["37f2591"] = "Hurricane, das sich nicht selbst unterbricht, wenn du die Taste während des Wirkens drückst.",
    ["e041704"] = "Moonfire auf den Cursor: um mehrere Feinde mit DOTs zu belegen (wechsle zu Insect Swarm für den anderen).",
    ["11b387e"] = "Feral Charge (Katze) und dann Prowl, wenn du nicht schon getarnt bist.",
    ["9bca5ec"] = "Wechselt die Gestalt, um dich von Wurzeln und Verlangsamungen zu befreien: von Bär zu Katze, von Katze zu Katze.",
    ["38e0846"] = "Eine Taste: Aquatic Form im Wasser, Travel Form im Freien, sonst Cat Form.",
    ["53406a7"] = "Wechselt nur einmal in Dire Bear Form, ohne sie zu verlassen, wenn du erneut drückst.",
    ["b18da61"] = "Growl auf den Fokus, dann auf den Cursor, dann auf das Ziel.",
    ["beb6029"] = "Nature's Swiftness und sofort Healing Touch: sofortige Notfallheilung (verlässt die Gestalt und bricht den Zauber ab).",
    ["8c5c182"] = "Im Kampf können keine Makros erstellt werden: Versuche es später erneut.",
    ["e3c93a8"] = "Makros: %d erstellt, %d aktualisiert%s. Öffne sie mit /macro und ziehe sie auf deine Leisten.",
    ["99effc3"] = "%d nicht erstellt (du hast schon 18 Charaktermakros)",
    ["530c645"] = "Für diese Spezialisierung gibt es keine Makros.",
    ["1e74c8f"] = "BuildBeast erstellt %s Makros für deinen Charakter:\n%s\n\nFalls sie schon existieren, werden sie aktualisiert. Danach ziehst du sie auf deine Leisten.",
    ["d8354a3"] = "Erstellen",
    ["160009a"] = "Abbrechen",
    ["054716f"] = "Krieger",
    ["3e76e85"] = "Paladin",
    ["69c8129"] = "Jäger",
    ["dd6c053"] = "Schurke",
    ["3a3f441"] = "Priester",
    ["fabeb14"] = "Schamane",
    ["a5a0a92"] = "Magier",
    ["8b0635d"] = "Hexenmeister",
    ["3d8e8ed"] = "Druide",
    ["ce774d9"] = "JA",
    ["c2f3f48"] = "NEIN",
    ["672c529"] = "ÄHNLICH",
    ["656ff24"] = "Bear Form, Growl, Maul (Klassenquest), Nature's Grasp, Demoralizing Roar",
    ["50d1ea3"] = "Bash; Quest für Cure Poison",
    ["2290f2a"] = "Swipe; Quest für Aquatic Form",
    ["227f378"] = "Faerie Fire (jetzt auch in den Gestalten), Hibernate",
    ["469f184"] = "Cat Form (Quest), Prowl, Claw, Rip, Shred, Starfire, Rebirth, Omen of Clarity",
    ["eda7053"] = "Mark of the Wild auf dich selbst. Eröffne mit Wrath und wirke es weiter. Wenn das Mana knapp wird, erledige das Monster mit der Waffe, damit das Mana zurückkommt. Heile dich zwischen den Kämpfen mit Healing Touch.",
    ["3d495a9"] = "Halte Mark of the Wild und Thorns auf dir und wirke Rejuvenation vor dem Kampfbeginn. Eröffne mit Wrath, füge Moonfire hinzu und wirke weiter Wrath. In einem überfüllten Gebiet eröffne mit Moonfire, das ist sofort wirksam.",
    ["bb21cc8"] = "Die Klassenquest gibt dir Bear Form, Growl und Maul. Nature's Grasp wurzelt das nächste Monster, das dich trifft; Demoralizing Roar ist für die Bärengestalt.",
    ["a9ba21f"] = "Enrage gibt dir sofort Wut und in 10 Sekunden noch mehr, senkt aber deine Rüstung.",
    ["9c7f3ca"] = "Feral ist die Katzen- und Bärenspezialisierung und die, die am flüssigsten levelt: Prowl und Dash bringen dich von einem Ziel zum nächsten und du hältst fast nie wegen Mana an. In Bear Form: Mark of the Wild und Thorns auf dich, und lass die Wut aus deinen Treffern Maul bezahlen, das dem nächsten Treffer Schaden hinzufügt. Gegen mehrere Monster Demoralizing Roar, um sie zu schwächen.",
    ["ce230c2"] = "In Bear Form: Enrage vor dem Pull (der Rüstungsverlust fällt weniger ins Gewicht), Faerie Fire senkt die Rüstung des Monsters, Swipe ist der Füller und Maul gibt die übrige Wut aus. Bei mehreren Monstern zuerst Demoralizing Roar, dann Swipe.",
    ["78a0920"] = "Cat Form: zuerst Mark of the Wild und Thorns. Eröffne aus Prowl mit Shred (Prowl bringt dich hinter das Monster), dann Faerie Fire, dann Claw, um Combopunkte aufzubauen, oder Shred, wenn du hinten stehst. Mit vier oder mehr Combopunkten Rip, wenn das Monster lange genug lebt. Bear Form bleibt gegen mehrere Monster besser: Die Katzengestalt hat nichts, was mehr als eines trifft.",
    ["540175c"] = "Rake: eröffne aus Prowl mit Shred, Faerie Fire, dann Rake, und halte dessen Blutung immer aktiv auf einem Monster, das lange genug lebt; dann Claw oder Shred von hinten. Mit 4 oder mehr Punkten: Rip, wenn das Monster lebt, Ferocious Bite zum Abschluss.",
    ["87e3251"] = "Lacerate (Bär): eine Blutung, die sich bis zu 5-mal stapelt; gegen ein einzelnes Monster ist sie dein Füller, und Maul gibt die übrige Wut aus. Bei mehreren Monstern Demoralizing Roar und dann Swipe. Blood Frenzy: In Bärengestalt gibt jeder kritische Treffer 5 Wut, in Katzengestalt gibt ein kritischer Treffer mit einer Combopunkt-Fähigkeit einen mehr.",
    ["25dc320"] = "Predatory Discipline: Ferocious Bite gewinnt weiter Schaden aus der zusätzlichen Energie, verbraucht sie aber nicht.",
    ["042c952"] = "Ravage: eröffne aus Prowl mit Ravage (du musst hinter dem Monster stehen), dann Faerie Fire, Rake mit immer aktiver Blutung, dann Claw oder Shred von hinten; mit 4 oder mehr Punkten Rip oder Ferocious Bite zum Abschluss. Poised nimmt deinem ersten Treffer 10 Energie ab, wenn du mit voller Energie beginnst.",
    ["4560b4d"] = "Dire Bear Form: Enrage vor dem Pull, Faerie Fire, Primal Bite bei jeder Abklingzeit (ein starker Biss mit 6 Sekunden Abklingzeit und viel Bedrohung), Lacerate dazwischen gegen ein einzelnes Monster und Maul, um den Rest auszugeben; bei mehreren Monstern Demoralizing Roar und Swipe statt Lacerate.",
    ["ff10d54"] = "Katze: Shifting Power, wenn du weniger als 50 Energie hast (verwandelt Mana in 40 Energie, 8 Sekunden Abklingzeit).",
    ["0d8ecd7"] = "Feral will vor allem den Schaden pro Sekunde der Waffe, weil deine Gestalt darauf beruht, und die Waffengeschwindigkeit zählt nicht. Dann Trefferwertung (Hit), kritische Treffer, Beweglichkeit und Stärke.",
    ["4a841e3"] = "Guardian ist der Bär: er nutzt denselben Talentplan wie Feral. Bear Form mit Mark of the Wild und Thorns auf dir; die Wut aus deinen Treffern bezahlt Maul. Gegen mehrere Monster Demoralizing Roar.",
    ["7b551a8"] = "Enrage vor dem Pull, Faerie Fire auf das Monster, Swipe als Füller und Maul mit der übrigen Wut. Bei mehreren Monstern Demoralizing Roar, dann Swipe.",
    ["af4c8fb"] = "Lacerate ist dein Füller gegen ein einzelnes Monster (stapelt sich bis zu 5-mal); Maul gibt die übrige Wut aus. Bei mehreren Monstern Demoralizing Roar und Swipe.",
    ["5213241"] = "Dire Bear Form: Enrage vor dem Pull, Faerie Fire, Primal Bite bei jeder Abklingzeit (6 Sekunden, viel Bedrohung), Lacerate dazwischen gegen ein einzelnes Monster und Maul für den Rest; bei mehreren Monstern Demoralizing Roar und Swipe statt Lacerate.",
    ["fc61247"] = "Der Bär will den Schaden pro Sekunde der Waffe (die Geschwindigkeit zählt nicht), dann Trefferwertung (Hit), kritische Treffer, Beweglichkeit und Stärke. Für die Bärengestalt sind auch Stärke und Zaubermacht in Ordnung, und Ausdauer zählt mehr, wenn du tankst.",
    ["25acd2a"] = "Balance und Restoration beginnen gleich: Improved Wrath (eine halbe Sekunde weniger Zauberzeit und halbes Mana) und Nature's Focus. Balance startet langsam, wird aber schneller, wenn Insect Swarm zu Moonfire auf jedem Monster hinzukommt.",
    ["9c1fb9f"] = "Mark of the Wild und Thorns auf dich, Rejuvenation vor dem Kampfbeginn. Eröffne mit Wrath oder mit Moonfire, wenn das Gebiet überfüllt ist. Moonfire und Insect Swarm auf das Monster (ein DOT, der auch seine Trefferchance senkt), dann Wrath. Regrowth, wenn du Heilung brauchst, Nature's Grasp, bevor ein zweites Monster eintrifft.",
    ["7f51b3b"] = "Moonfire und Insect Swarm auf jedes Monster, das du bekämpfst, dann Wrath. Bei drei oder mehr Monstern Hurricane.",
    ["c845919"] = "Bei drei oder mehr Monstern Barkskin und dann Hurricane.",
    ["d66aa4c"] = "Eclipse: Jedes Wrath nimmt deinen nächsten beiden Starfire eine halbe Sekunde ab, sodass Starfire endlich in die Rotation kommt: ein Wrath, gefolgt von zwei Starfire.",
    ["7e94c11"] = "Moonkin Form: viel Rüstung, 3% kritische Treffer für die Gruppe und Omen of Clarity löst doppelt so oft aus; in dieser Gestalt kannst du keine Heilzauber wirken, also verlasse sie für Regrowth und kehre zurück. Rotation: Moonfire und Insect Swarm, dann ein Wrath und zwei Starfire.",
    ["ef6797a"] = "Für Balance und Restoration kommt zuerst die Zaubermacht, dann Intelligenz, kritische Treffer und Willenskraft; Restoration fügt bei 60 Heilungsmacht hinzu. Ein Zauberstab kann aus einer Fraktionsquest kommen.",
    ["a91a8ac"] = "Restoration levelt am langsamsten, weil Heilen keine Monster tötet: Du kannst als Balance oder Feral leveln und trotzdem Dungeons heilen.",
    ["7a2110b"] = "Mark of the Wild und Thorns auf dich, Rejuvenation vor dem Kampfbeginn. Eröffne mit Wrath oder Moonfire in einem überfüllten Gebiet, dann Moonfire und Insect Swarm auf das Monster und Wrath. Regrowth, wenn du Heilung brauchst, Nature's Grasp, bevor ein zweites Monster eintrifft.",
    ["937f66e"] = "Swiftmend: sofortige Heilung auf jeden, der dein Rejuvenation oder Regrowth hat. Wenn du Schaden nimmst, Swiftmend auf dein Rejuvenation und dann Regrowth, wenn mehr nötig ist. Bei drei oder mehr Monstern Hurricane.",
    ["2061d06"] = "Nature's Swiftness: Dein nächster Naturzauber ist sofort wirksam. Lass es außerhalb der Rotation, für den Moment, in dem du sofort eine große Heilung brauchst.",
    ["1164b95"] = "Wild Growth: heilt das Ziel und seine Gruppe über 7 Sekunden, am Anfang stärker: in der Gruppe, wenn mehr als einer verletzt ist.",
    ["8f8a34a"] = "Aspect of the Hawk, das Tier zähmen (Klassenquest: Tame Beast, Call Pet, Feed Pet, Revive Pet)",
    ["2b3db50"] = "Auto Shot startet von selbst: Steh vor jedem Schuss eine halbe Sekunde still und lass das Monster kommen. Raptor Strike, wenn es dich erreicht. Innerhalb von 8 Metern funktionieren Distanzschüsse nicht.",
    ["9329f10"] = "Füge Serpent Sting als Eröffnung hinzu, nur bei Monstern, die lange leben: Wenn es in wenigen Sekunden stirbt, ist der Schaden verschwendet.",
    ["d2b7bf1"] = "Hunter's Mark vor dem Pull, dann Serpent Sting. Arcane Shot, wenn du Mana hast.",
    ["85f72cd"] = "Der Kern ist Auto Shot, mit Arcane Shot, wenn du Mana hast. Vor dem Pull Hunter's Mark, dann Serpent Sting als Eröffnung. Während das Monster auf dich zurennt, verlangsamt Concussive Shot es; Raptor Strike, wenn es dich erreicht.",
    ["71067ff"] = "Du hast das Tier: Schick es ein paar Sekunden voraus, dann Serpent Sting. Halte immer Aspect of the Hawk aufrecht und füttere das Tier. Concussive Shot, wenn sich das Monster dir zuwendet, Raptor Strike als letzter Ausweg.",
    ["bb6f64b"] = "Rapid Fire (+40% Angriffsgeschwindigkeit für 15 Sekunden) bleibt außerhalb der Rotation: Spar es für den Pull auf, der es braucht.",
    ["ebe54cf"] = "Der Kern ist Aimed Shot jedes Mal, wenn es bereit ist (2 Sekunden Zauberzeit, 6 Sekunden Abklingzeit, geteilt mit Multi-Shot), mit Auto Shot in den Lücken. Vor dem Pull Hunter's Mark, Tier voraus, dann Serpent Sting. Arcane Shot, wenn du Mana hast. Wenn das Monster dich erreicht: Disengage. Bei mehreren Monstern: Multi-Shot statt Aimed Shot.",
    ["c943332"] = "Der Kern sind die Falken (Summon Hawk): Jeder Falke hält 18 Sekunden, zwei können draußen sein; beschwöre einen neuen Falken, wenn einer der beiden ausläuft. Dann Aimed Shot, wenn bereit, und Auto Shot in den Lücken. Arcane Shot nutzt dieselbe Abklingzeit wie die Falken, also warte bis nach ihnen. Der Rest wie vorher.",
    ["ab9f050"] = "Füge Intimidation hinzu: Wenn sich das Monster gegen dich wendet, betäubt es und gibt dem Tier Bedrohung; Disengage, wenn es nicht bereit ist. Bei mehreren Monstern: zuerst Explosive Trap, dann Multi-Shot auf der Abklingzeit von Aimed Shot.",
    ["bf06335"] = "Bestial Wrath (2 Minuten) und Volley bleiben außerhalb der Rotation: Setze sie von Hand bei gefährlichen Pulls oder großen Gruppen ein. Ab 42 gehen fast alle Punkte in Marksmanship: Die Rotation ändert sich nicht.",
    ["e096af7"] = "Beast Mastery schießt aus der Ferne: Es zählen der DPS der Distanzwaffe und dann Beweglichkeit. Die Nahkampfwaffe dient nur wegen ihrer Werte.",
    ["b35c3c9"] = "Der Kern ist Aimed Shot jedes Mal, wenn es bereit ist, mit Auto Shot in den Lücken. Nach dem Vorsprung des Tieres muss der erste Schuss der stärkste sein: Mit wartendem Rapid Killing ist es Aimed Shot. Vor dem Pull Hunter's Mark und Tier voraus; Serpent Sting auf jedes Monster, denn wenn es mit Serpent Sting stirbt, macht dein nächster Schuss innerhalb von 20 Sekunden bis zu 20% mehr. Arcane Shot, wenn du Mana hast. Wenn das Monster dich erreicht: Disengage. Bei mehreren Monstern: Multi-Shot statt Aimed Shot.",
    ["cf4e14e"] = "Vor dem Pull auch Trueshot Aura, zusätzlich zu Hunter's Mark.",
    ["51e16cf"] = "Sniper Shot ist dein stärkster Schuss: 4 Sekunden Zauberzeit, 15 Sekunden Abklingzeit, bis zu 45 Meter, und 10 Sekunden lang reichen deine nächsten drei Schüsse 10 Meter weiter. Nutze ihn als ersten Schuss nach dem Vorsprung des Tieres, wenn du Zeit für das Wirken hast, besser mit wartendem Rapid Killing; sonst Aimed Shot. Bei mehreren Monstern: zuerst Explosive Trap, dann Multi-Shot auf der Abklingzeit von Aimed Shot.",
    ["c8aaa16"] = "Der Kern sind die Falken (Summon Hawk): ein neuer jedes Mal, wenn einer der beiden ausläuft. Dann Aimed Shot, wenn bereit, und Auto Shot in den Lücken; Sniper Shot als erster Schuss, wenn du Zeit hast. Arcane Shot wartet bis nach den Falken.",
    ["1fe9ee6"] = "Marksmanship schießt aus der Ferne: Es zählen der DPS der Distanzwaffe (bei Gleichstand besser eine langsamere mit großen Treffern, denn Aimed Shot beruht auf einem Waffentreffer) und Beweglichkeit. Mit Careful Aim zählt Intelligenz auch als Angriffskraft, zusätzlich zum Mana. Die Nahkampfwaffe dient nur wegen ihrer Werte.",
    ["184fc61"] = "Survival kämpft an zwei Orten. Auf Distanz: Multi-Shot jedes Mal, wenn es bereit ist (es ist sofort wirksam und teilt die Abklingzeit mit Aimed Shot, du nutzt Aimed Shot also fast nie), dazu Serpent Sting, Arcane Shot und Auto Shot. Im Nahkampf: Immolation Trap, dann Raptor Strike (sofort, 6 Sekunden Abklingzeit) und Mongoose Bite nach einem Ausweichen. Hunter's Mark vor dem Pull und das Tier geht zuerst rein.",
    ["d85837a"] = "Strider Kick: ein Tritt mit dem vollen Schaden der Waffe, der dich 3 Sekunden lang 30% schneller macht: Das ist die Taste, die den Nahkampf beendet und dich auf Distanz zurückbringt. Im Nahkampf zuerst Immolation Trap, Mongoose Bite, wenn nutzbar, Raptor Strike. Auf Distanz Multi-Shot, wenn bereit, Serpent Sting, Arcane Shot, Auto Shot. Bei mehreren Monstern nimmt Explosive Trap den Platz von Immolation Trap ein, weil eine einzige Abklingzeit für alle Fallen gilt.",
    ["e7233e1"] = "Mit Lacerating Strikes hinterlässt jeder Mongoose Bite eine Blutung in Höhe von 40% des Trefferschadens, über 21 Sekunden.",
    ["10bfe36"] = "Survival schießt, trifft aber auch mit der Nahkampfwaffe (Raptor Strike und Strider Kick beruhen auf deren Schaden): Ein langsamer Zweihänder hilft. Dann zählt Beweglichkeit. Ab 49 macht Careful Aim Intelligenz auch als Angriffskraft nützlich.",
    ["0718298"] = "Blink, Evocation, Mana Shield, Blizzard, Fire Ward, Teleport zu zwei Hauptstädten (und Arcane Blast für Arcane und Fire)",
    ["ad986c1"] = "Conjure Mana Agate (der erste Manaedelstein)",
    ["3e67dd9"] = "Ice Armor; Klassenquest (der Zauberstab Ice Fury)",
    ["3ddbf7c"] = "Frostfire Bolt, erste Portale",
    ["3d9e7fb"] = "Halte immer Arcane Intellect und einen Rüstungszauber aufrecht (vorerst Frost Armor). Die Manaregeneration pausiert 5 Sekunden nach jedem Zauber, der Mana kostet: Ein fast totes Monster ist keinen vollen Zauber wert. Um Stufe 5 besorg dir einen Zauberstab (ein Verzauberer fertigt dir den Lesser Magic Wand, ab 13 den Greater Magic Wand): Bis zu den Talenten kann er so viel Schaden machen wie deine Zauber oder mehr und kostet kein Mana.",
    ["2991425"] = "Eröffne mit Frostbolt auf maximale Distanz, damit das Monster verlangsamt ankommt. Wirke weiter, während es sich nähert, dann Fire Blast zum Abschluss und der Zauberstab für den Rest.",
    ["5d6b9a7"] = "Frost Nova friert alles um dich herum ein: Schaden bricht sie, also kannst du zurückweichen und weiterwirken. Wenn das Monster in den Nahkampf kommt: Frost Nova und zurückweichen.",
    ["11f2d67"] = "Mit Missile Barrage: Eröffne aus der Ferne mit Frostbolt (Arcane und Frost) oder Fireball (Fire), wirke weiter und wenn der Proc auslöst, wirke Arcane Missiles: Sie werden zu einer kostenlosen Salve. Missile Barrage ist das Talent, das dir beim Leveln am meisten Mana spart.",
    ["b985201"] = "Evocation ist eine 8-Sekunden-Kanalisierung, die dir einen Großteil deines Manas zurückgibt. Blink bei Abklingzeit beim Laufen lässt dich etwa ein Fünftel schneller ankommen. Der Ruhestein wird besser für das Questgebiet genutzt, weil dich der Teleport schon in eine Hauptstadt bringt.",
    ["a601e53"] = "Arcane Blast: Jeder Zauber gibt dir Zauberschaden in Höhe von 12% deiner Intelligenz, bis zu 4 Aufladungen, die 18 Sekunden halten; jede Aufladung macht den nächsten Zauber 100% teurer. Frostbolt aus der Ferne, dann ein- bis dreimal Arcane Blast, bis Missile Barrage auslöst, dann Arcane Missiles. Lass die Aufladungen auslaufen, statt vier zu erreichen. Gib Clear Casting auf einem aufgeladenen Arcane Blast aus. Im Nahkampf: Frost Nova und zurückweichen. Fire Blast zum Abschluss und der Zauberstab.",
    ["e55eb73"] = "Arcane Wrath: ein schwerer Treffer mit 6 Sekunden Abklingzeit (der Zusatzschaden entspricht 5% deines maximalen Manas). Frostbolt aus der Ferne, dann Arcane Wrath, ein- bis dreimal Arcane Blast bis Missile Barrage und Arcane Missiles; Frost Nova, wenn es näher kommt, wieder Arcane Wrath, dann Fire Blast und der Zauberstab zum Töten. Lass die Aufladungen auslaufen, sonst saugen dich die steigenden Kosten leer; Clear Casting nur auf einem aufgeladenen Arcane Blast oder einem Arcane Wrath, nie auf einem billigen Zauber.",
    ["65a5bf0"] = "Presence of Mind: Dein nächster Zauber mit einer Zauberzeit unter 10 Sekunden ist sofort wirksam.",
    ["c51b464"] = "Arcane Power: +30% Schaden für 15 Sekunden, zum Preis von +30% Mana.",
    ["dfc4101"] = "Eröffne mit Pyroblast oder Frostbolt aus der Ferne, dann Arcane Wrath. Ein- bis dreimal Arcane Blast bis Missile Barrage, dann die Geschosse. Ab 58 Fire Blast bei Abklingzeit und Pyroblast, wenn Heating Up 3 Aufladungen erreicht.",
    ["9226a40"] = "Für jede Spezialisierung kommt die Zaubermacht zuerst, weil deine Zauber stark mit ihr wachsen. Intelligenz erhöht das Mana und ein wenig die kritischen Treffer; Willenskraft verkürzt die Trinkpausen, und für Arcane zählt sie viel, weil es schnell Mana verbrennt.",
    ["ebbbb02"] = "Fireball aus der Ferne. Ein- oder zweimal Arcane Blast, bis Missile Barrage auslöst, dann die Geschosse. Fire Blast bei Abklingzeit. Ein Monster mit wenig Leben muss nicht auf Distanz gehalten werden: Lass es dich ein paar Mal treffen, unter 15% erledigt es der Zauberstab.",
    ["9e5f918"] = "Scorch füllt die Lücken, auch wenn das Monster an dir dran ist.",
    ["ab79a6b"] = "Eröffne mit Frostfire Bolt aus der Ferne, dann ein- oder zweimal Arcane Blast, bis Missile Barrage auslöst, und die Geschosse. Fire Blast bei Abklingzeit, Scorch zum Füllen der Lücken, der Zauberstab für die letzten 15%.",
    ["bece8ec"] = "Pyroblast und Heating Up: Jeder nicht periodische kritische Treffer von Fireball, Frostfire Bolt, Fire Blast oder Scorch macht dein nächstes Pyroblast ein Viertel schneller, bis zu 3 Aufladungen, und Fire Blast fügt bei jedem Schaden eine Aufladung hinzu. Wirke Pyroblast, wenn Heating Up 3 Aufladungen erreicht.",
    ["196edb9"] = "Für jede Spezialisierung kommt die Zaubermacht zuerst. Intelligenz erhöht das Mana und ein wenig die kritischen Treffer; Willenskraft verkürzt die Trinkpausen.",
    ["38bc29a"] = "Frost beginnt mit Precision: Zwei Punkte bringen die Trefferchance gegen Monster deiner Stufe auf 100%.",
    ["c690916"] = "Frostbite: Deine Frosteffekte haben eine Chance von 15%, das Ziel 5 Sekunden einzufrieren. Ice Lance (ab 27): gegen ein eingefrorenes Ziel 300% mehr Schaden, mit 8 Sekunden Abklingzeit, geteilt mit Fire Blast.",
    ["1f1ed9a"] = "Frostbolt aus der Ferne und wirke weiter, während das Monster ankommt. Wenn Frostbite das Ziel einfriert: ein Frostbolt mit Ice Lance direkt dahinter; wenn Ice Lance nicht bereit ist, Cone of Cold. Im Nahkampf: Frost Nova und zurückweichen, dann Frostbolt und Ice Lance auf das eingefrorene Monster. Missile Barrage: wirke die Geschosse oder spare es für das nächste Monster auf, wenn dieses fast tot ist. Fire Blast oder der Zauberstab für ein schwaches, nicht eingefrorenes Monster.",
    ["2e43c7c"] = "Mit Fingers of Frost behandeln deine nächsten zwei Zauber das Ziel als eingefroren: der erste auf einem Frostbolt, der zweite auf einem Frostbolt mit Ice Lance (oder mit Cone of Cold, wenn Ice Lance noch nicht bereit ist). Seine Stärke liegt in den 30ern: Nach Shatter erleidet ein eingefrorenes Ziel deine härtesten Treffer.",
    ["cecd125"] = "Zuerst Ice Barrier, und wirke es erneut, wenn die Minute abläuft: Neben dem Schild gibt es eine Minute lang 15% mehr Frostschaden.",
    ["959453a"] = "Winter's Chill: Frostbolt und Ice Lance stapeln sie bis zu 5-mal auf dem Ziel, und das nächste Cone of Cold macht 20% mehr pro Aufladung.",
    ["5a9d3eb"] = "Redemption (Klassenquest)",
    ["3d343ad"] = "Seal of Command (Retribution-Talent), Seal of Justice",
    ["32b558d"] = "Doppelspezialisierung und Reittier",
    ["38d0905"] = "Vor dem Pull Blessing of Might und Devotion Aura. Dann drei Schritte: Seal of Righteousness, Judgment, während du auf das Monster zurennst, Holy Strike. Danach Judgment und Holy Strike jedes Mal, wenn sie bereit sind, und erneuere das Siegel nur, wenn es bald endet (Judgment verbraucht es nicht mehr und ist außerhalb der globalen Abklingzeit). Mana ist auch deine Heilung: Wenn der nächste Treffer das Monster tötet, überspringe die Taste. Wenn du einen Kampf mit übrigem Mana beendest, verwandle es mit Holy Light in Leben. In Gefahr: zuerst Divine Protection auf dich, dann heilen.",
    ["f580de7"] = "Consecration, wenn du gegen mehrere Feinde kämpfst oder Mana übrig hast: Es kostet mehr als Judgment und Holy Strike zusammen und braucht 8 Sekunden, um seinen ganzen Schaden zu machen. Exorcism auf jeden Untoten oder Dämon, sogar aus 30 Metern.",
    ["2ea2c89"] = "Füge Hammer of Wrath hinzu: Es erledigt Feinde unter 20% Leben.",
    ["c8d4778"] = "Retribution und Protection beginnen im selben Baum mit fast denselben Talenten. Statt Deflection (5% Parieren) kannst du Benediction wählen: Alle Sofortfähigkeiten kosten 10% weniger Mana, und Consecration wird leichter bezahlbar.",
    ["a81d5b1"] = "Mit Seal of Command: Blessing of Kings oder Might und Retribution Aura. Auf ein Monster, das lange lebt: zuerst Judgment von Seal of the Crusader (das Monster erleidet mehr heiligen Schaden), dann wechsle zu Seal of Command, wenn du eine langsame Waffe hast; mit einer schnellen Waffe oder viel Zauberschaden ist Seal of Righteousness besser. Dann Judgment und Holy Strike bei jeder Abklingzeit. Trick: Das Judgment von Seal of Command macht gegen ein betäubtes Ziel fast doppelt so viel, also eröffne mit Hammer of Justice und dann Judgment.",
    ["733e5e6"] = "Sacred Arbiter: Holy Strike trifft 20% stärker und erneuert jedes Judgment auf dem Ziel, auch die anderer Paladine.",
    ["a01f90a"] = "Champion of the Light verwandelt bis zu 60% deiner Intelligenz in Zauberschaden: Ausrüstung mit Zaubermacht wird noch besser. Bei 40 Unsealed Wrath: Treffer behalten eine Kopie des aktiven Siegels (bis zu 3), und der Siegelwechsel lohnt sich wieder.",
    ["5f3698b"] = "Die Waffe ist das Wichtigste: ideal mit Zaubermacht und viel Schaden. Mit Seal of Command sind langsame, schwere Waffen die besten (Holy Strike und das Siegel machen mehr Schaden). Beim Rest zuerst Stärke oder Angriffskraft, dann Ausdauer, dann Zaubermacht.",
    ["a531e3f"] = "Seal of Fury ist das Siegel des Tanks: Jeder Treffer macht zusätzlichen heiligen Schaden, und mit dem Schild erhältst du eine Absorption in Höhe der Hälfte dieses Schadens. Sein Judgment lässt dich 3 Sekunden lang aus 10 Metern spotten. Righteous Fury erhöht deine gesamte Bedrohung um 33%. Ab 22 wechselst du in den Protection-Baum, nach Pursuit of Justice.",
    ["8279baa"] = "Blessing of Kings, Retribution Aura und Righteous Fury aktiv. Halte immer Seal of Fury aufrecht. Richte, während du auf das Monster zurennst, um zu spotten. Setze Consecration, sobald du im Nahkampf bist, wenn das Mana es zulässt. Dann Holy Strike bei jeder Abklingzeit und Exorcism auf Untote und Dämonen. Sammle bis zu vier Feinde und verbrenne alles mit Consecration.",
    ["34e2900"] = "Shield Specialization: Ein Block gibt dir 4% deines maximalen Manas zurück, höchstens alle 3 Sekunden: Das ist ein großer Teil deines Manas.",
    ["cc3ac76"] = "Templar's Bulwark: ein Schild, der 8 Sekunden lang Schaden in Höhe deines gesamten Lebens absorbiert, dir aber eine Minute lang Forbearance gibt. Ab 37 Swift Judgement: Das Judgment des Siegels löst von selbst aus mit 1 Minute Abklingzeit, du hast also einen zweiten Spott.",
    ["be55413"] = "Holy Shield: 10 Sekunden lang blockst du öfter und bis zu 4 Blocks machen heiligen Schaden. Reckoning (ab 43) kann nach einem Block oder einem erlittenen kritischen Treffer einen Zusatzangriff geben.",
    ["e76d8e9"] = "Für Protection kommt die Zaubermacht zuerst (Seal of Fury, Holy Shield und Consecration machen heiligen Schaden), dann Stärke und Ausdauer. Bei der Waffe ist eine schnellere besser: Seal of Fury schlägt bei jedem Treffer zu. Eine Waffe mit Zaubermacht darf ruhig etwas weniger Schaden haben.",
    ["05e5db7"] = "Shadow Word: Pain; kurze Klassenquest (ein Gewand)",
    ["c95888a"] = "Mind Blast, Resurrection; die Völkerquest lehrt die erste Fähigkeit nur deines Volkes",
    ["091c0cd"] = "Holy Fire, Flash Heal, Devouring Plague, Fear Ward, Mind Soothe, Shackle Undead; die zweite Volksfähigkeit",
    ["71b2a72"] = "Fortitude auf dich vor dem Pull. Eröffne mit Smite, wirke Shadow Word: Pain auf das Ziel und erledige es mit dem Zauberstab, der kein Mana kostet und am Anfang einen großen Teil deines Schadens macht (steh vor dem Einsatz eine halbe Sekunde still). Wenn das Monster dich erreicht, zuerst Power Word: Shield. Das Wichtigste ist ein guter Zauberstab: Ersetze ihn jedes Mal, wenn du einen besseren findest.",
    ["e023128"] = "Mind Blast ist der starke Treffer mit kurzer Abklingzeit. Die ersten sieben Talentpunkte sind für alle Spezialisierungen gleich: Wand Specialization (10-11) und Spirit Tap (12-16). Mit Spirit Tap verdoppelt jeder Kill eines Monsters, das Erfahrung gibt, deine Willenskraft für 15 Sekunden, und in dieser Zeit läuft die Hälfte der Manaregeneration beim Wirken weiter: weniger Trinkpausen.",
    ["8df287d"] = "Inner Fire: zusätzliche Rüstung, jeder erlittene Treffer verbraucht eine Aufladung. Halte es zusammen mit Fortitude immer auf dir und wirke es neu, wenn es endet.",
    ["bebe913"] = "Psychic Scream lässt nahe Feinde fliehen, aber Vorsicht: Sie können andere Monster zurückholen.",
    ["ffa87bf"] = "Der Lehrer bringt dir heute mehr bei als auf jeder anderen Stufe: Holy Fire (langsame, aber starke Eröffnung, brennt auch über Zeit), Flash Heal (schnell, aber teuer), Devouring Plague (Schaden über Zeit, der dich heilt) und andere.",
    ["084f80e"] = "Shadow ist die empfohlene Spezialisierung zum Leveln allein: Die Punkte gehen in Shadow Word: Pain, Mind Blast und Mind Flay, damit Monster früher sterben.",
    ["f33a503"] = "Wirke Shield auf dich, wenn das Monster dich erreicht. Eröffne mit Mind Blast, dann Shadow Word: Pain. Ab 27 auch Devouring Plague und Mind Flay, und nach Shadow Word: Pain füge Vampiric Embrace hinzu, damit dein Schattenschaden dich heilt. Dann erledige mit dem Zauberstab. Wenn das Mana knapp ist, überspringe Devouring Plague und Mind Flay.",
    ["496ef3d"] = "Shadow Word: Death ist plötzlicher Schaden, aber wenn das Ziel überlebt, erleidest du 30% deines maximalen Lebens: Spar es für den letzten Schlag auf.",
    ["edd0d02"] = "Shadowform: Bleib im Kampf in Shadowform (+10% Schattenschaden, Schattenzauber kosten halbes Mana, -15% physischer Schaden, aber du kannst keine Heilzauber wirken: verlasse sie vor dem Heilen). Eröffne mit Mind Blast, dann Shadow Word: Pain, Vampiric Embrace, Devouring Plague und Mind Flay. Wenn ein weiterer Treffer das Monster tötet: Shadow Word: Death, oder überlasse das letzte Stück dem Zauberstab. Shield auf dich, wenn das Monster dich erreicht.",
    ["b912dce"] = "Für Shadow kommt zuerst die Zaubermacht (auch Schattenmacht ist gut: fast dein ganzer Schaden ist Schatten), dann kritische Treffer und Trefferwertung (Hit). Der Zauberstab ist sehr wichtig: Am Anfang macht er einen großen Teil des Schadens.",
    ["8e3f775"] = "Discipline ist die Heilspezialisierung, die wir zum Alleinspielen empfehlen: Ab 20 fügt Power in Light Smite Schaden hinzu.",
    ["916c9c2"] = "Eröffne mit Holy Fire aus der Ferne, Smite, während das Monster ankommt, dann Mind Blast, Shadow Word: Pain und der Zauberstab. Wenn der Kampf schlecht läuft: Shield auf dich, dann heilen: Flash Heal, wenn es schnell gehen muss, Heal, wenn du Zeit hast.",
    ["a80f7e5"] = "Penance: eine Salve heiliger Treffer, die einen Feind verletzt oder einen Verbündeten heilt, 12 Sekunden Abklingzeit, der erste Treffer landet sofort.",
    ["037a666"] = "Zuerst Shield auf dich. Eröffne mit Holy Fire aus der Ferne. Smite, während das Monster läuft, dann Penance auf dasselbe Ziel, weil Power in Light es härter treffen lässt. Dann Mind Blast und Shadow Word: Pain. Zum Abschluss Shadow Word: Death, wenn ein Treffer tötet, sonst der Zauberstab. Jedes Mal, wenn Weakened Soul verschwindet, kannst du dich erneut schützen.",
    ["9d0affc"] = "Power Infusion: +20% Schaden und Heilung für 15 Sekunden, auf dich oder einen Freund: Wirke es auf dich, kurz bevor du eröffnest, jedes Mal, wenn es bereit ist. Bei 60 Inner Focus für Notfälle: Der nächste Zauber ist kostenlos.",
    ["8e7cd8d"] = "Für Discipline und Holy suche Heilungsmacht und Manaregeneration, dann Intelligenz und Willenskraft. Wähle die Waffe mit genau diesen Werten: Es ist egal, ob es ein Stab oder eine Einhandwaffe mit Nebenhand ist.",
    ["c5c1351"] = "Wirke Shield und Renew auf dich vor dem Pull. Dann eröffne mit Holy Fire, Smite, während das Monster ankommt, Mind Blast und Shadow Word: Pain. Erledige mit Shadow Word: Death, wenn es tötet, oder mit dem Zauberstab.",
    ["575bdd0"] = "Holy Nova schadet jedem nahen Feind und heilt die Gruppe: Es kostet viel Mana, also nutze es, wenn mehrere Feinde an dir dran sind, oder wenn es kostenlos ist (Searing Light ab 43: Holy Fire kann die nächste Holy Nova kostenlos machen).",
    ["6953353"] = "Wirke vor dem Pull Shield, Renew und Prayer of Mending auf dich (es heilt, wenn das Ziel das nächste Mal Schaden erleidet, und springt dann auf einen anderen der Gruppe, 10 Sekunden Abklingzeit).",
    ["a5c9096"] = "Für Holy suche Heilungsmacht und Manaregeneration, dann Intelligenz und Willenskraft. Wähle die Waffe mit genau diesen Werten.",
    ["aa71e89"] = "Backstab (braucht einen Dolch, nur von hinten), Pick Pocket",
    ["2e3c463"] = "Slice and Dice, Sprint, Sap; Klassenquest (Blade of Cunning)",
    ["3a2246d"] = "Ambush (braucht einen Dolch), Poised (passiv)",
    ["8abd601"] = "Rupture; Giftquest: Instant Poison und Crippling Poison",
    ["6c840ea"] = "Shank (neu in Forever)",
    ["f3d428e"] = "Mutilate (Assassination-Talent)",
    ["3e307c7"] = "Death Mark (Subtlety-Talent), Slice and Dice Rang 2",
    ["f14c847"] = "Shank Rang 2",
    ["a554ba3"] = "Geh zum Monster und nutze Sinister Strike, solange du Combopunkte hast, dann Eviscerate: mehr Punkte, stärkerer Treffer. Stealth kann vorerst in der Leiste bleiben. Wenn der Kampf schlecht läuft: Evasion und Gouge, um einen Zauber zu stoppen oder ein paar Sekunden zu gewinnen.",
    ["44b2b7e"] = "Slice and Dice (ein Finisher: du greifst 20% schneller an, länger mit mehr Punkten), Sprint (50% schneller für 15 Sekunden, bricht Stealth nicht) und Sap, um einen Humanoiden vor Kampfbeginn aus dem Kampf zu nehmen.",
    ["665b56f"] = "Rupture: eine längere Blutung mit mehr Punkten. Mit der Giftquest Instant Poison und Crippling Poison.",
    ["d06b2e0"] = "Shank: ein Nebenhandtreffer, der nicht verfehlen kann; der erste Rang kostet 5 Energie, gibt 15 zurück und lädt in 10 Sekunden nach. Ab 26 Cheap Shot aus der Tarnung: betäubt 4 Sekunden und gibt 2 Punkte.",
    ["6974c7f"] = "Combat ist der Duellant: Er kämpft im Nahkampf mit der Waffe deiner Wahl, funktioniert mit jeder Waffe und braucht keine Tarnung zum Beginn. Sie ist die empfohlene zum Leveln allein.",
    ["cea5a19"] = "Riposte: Nach einem eigenen Parieren leuchtet es auf und trifft für das Anderthalbfache des Waffenschadens, entwaffnet das Monster 6 Sekunden lang und kostet nur 10 Energie bei 6 Sekunden Abklingzeit.",
    ["5288c4d"] = "Instant Poison auf beiden Waffen. Cheap Shot aus der Tarnung für einen harten Kampf, sonst sofort Sinister Strike. Riposte direkt nach einem Parieren. Sinister Strike für die Punkte mit Shank auf Abklingzeit: die ersten fünf Punkte in Slice and Dice, die nächsten fünf in Eviscerate.",
    ["869d1bf"] = "Mit zwei Monstern an dir: Blade Flurry (alle 2 Minuten, 15 Sekunden lang greifst du 20% schneller an und jeder Treffer trifft auch einen zweiten in der Nähe).",
    ["9fb5eb8"] = "Adrenaline Rush (alle 5 Minuten: Die Energie kommt 15 Sekunden lang doppelt so schnell zurück) für ein gefährliches Monster.",
    ["f8cc28b"] = "Cold Blood direkt vor einem großen Eviscerate.",
    ["625324b"] = "Lederrüstung mit Beweglichkeit: Das ist die, die du willst. Trefferwertung (Hit), kritische Treffer, Angriffskraft und Ausdauer sind nützlich. Combat kann jede Waffenart nutzen, weil Hack and Slash für jede einen Bonus gibt: Schwerter und Äxte, Dolche und Faustwaffen, Streitkolben.",
    ["d01cb25"] = "Assassination ist der Giftmischer: Gifte und Finisher werden immer stärker, und bei 40 kommt Mutilate.",
    ["9eb3d72"] = "Instant Poison auf beiden Waffen. Aus der Tarnung eröffne mit Garrote oder Cheap Shot. Sinister Strike für die Punkte und Shank auf Abklingzeit. Slice and Dice, dann Eviscerate; Spar Cold Blood für ein großes Eviscerate auf.",
    ["33aceb3"] = "Venom: 6 Sekunden nach jedem Shank treffen deine Gifte 30% stärker und 20% häufiger. Shank auf Abklingzeit.",
    ["88ede56"] = "Mutilate baut die Punkte auf: Es trifft mit beiden Waffen, 20% stärker auf einem vergifteten Ziel, und gibt 2 Punkte. Du brauchst zwei Dolche. Slice and Dice, Shank auf Abklingzeit für Venom, dann Eviscerate; Cold Blood auf ein großes Eviscerate.",
    ["20500ff"] = "Lederrüstung mit Beweglichkeit. Assassination braucht Dolche für Backstab, Ambush und Mutilate. Trefferwertung (Hit), kritische Treffer, Angriffskraft und Ausdauer sind nützlich.",
    ["5259278"] = "Subtlety ist der Hinterhältige: Er eröffnet jeden Kampf aus den Schatten mit einem Dolch in der Hand.",
    ["64f4a07"] = "Dolch in der Haupthand, Instant Poison auf beiden Waffen. Nähere dich dem Monster von hinten, Premeditation, dann Ambush, dann Ghostly Strike, dann Garrote. Sinister Strike baut den Rest auf; Shank auf Abklingzeit für Energie; Eviscerate schließt ab.",
    ["37c1365"] = "Hemorrhage baut die Punkte statt Sinister Strike auf.",
    ["c0f22d5"] = "Hemorrhage und Shank bauen die Punkte auf, und mit Boot Knife zählt jeder Shank doppelt. Death Mark speichert Schaden 6 Sekunden lang: Gib einen vollen Satz Punkte darauf aus, wenn das Monster lange genug lebt, dann Eviscerate zum Abschluss. Wenn der Kampf schlecht läuft, setzt Preparation Premeditation, Ghostly Strike und deine anderen Abklingzeiten zurück.",
    ["a993dd2"] = "Lederrüstung mit Beweglichkeit. Subtlety hält einen Dolch in der Haupthand (Ambush und Backstab verlangen ihn). Trefferwertung (Hit), kritische Treffer, Angriffskraft und Ausdauer sind nützlich.",
    ["abbb551"] = "Earth Shock; Erdtotem-Quest: Stoneskin Totem",
    ["8e8845b"] = "Feuertotem-Quest: Searing Totem",
    ["2be8a5e"] = "Ghost Wolf, Frost Shock, Lesser Healing Wave, Frostbrand Weapon, Healing Stream Totem (Wassertotem-Quest), Call of the Elements, Totemic Recall",
    ["0a8c77d"] = "Windfury Weapon, Reincarnation (braucht einen Ankh), Astral Recall, Grounding Totem",
    ["47fd721"] = "Chain Lightning, Windfury Totem; Lufttotem-Quest (die Sturmwaffen)",
    ["b821239"] = "Chain Heal, Kettenrüstung",
    ["d6b5209"] = "Rockbiter Weapon bleibt auf der Waffe und ab 8 kommt Lightning Shield vor dem Pull auf dich. Eröffne mit Lightning Bolt und sobald er da ist Earth Shock, das sofort wirkt; gegen einen Zauberwirker spare den Schock, um seinen Zauber zu unterbrechen. Wenn das Monster an dir dran ist, erledigen es die Nahkampftreffer. Wenn ein weiteres Monster kommt, setze Earthbind Totem: Es verlangsamt es und lässt dich kiten. Nach dem Kampf Healing Wave, wenn du verletzt bist.",
    ["fa734a3"] = "Jede Spezialisierung hat eine klare Rolle: Enhancement kämpft im Nahkampf mit einer großen Waffe, Totems und Schocks; Elemental bleibt auf Distanz mit Lightning Bolt, Chain Lightning und Fire Nova; Restoration heilt und ist in der Gruppe oder in Dungeons, nicht allein bei Quests. Wenn dir das Mana ausgeht, schlägt Enhancement weiter zu (der Kill dauert länger), Elemental leidet mehr.",
    ["b74be3c"] = "Flame Shock trifft sofort mit Feuer und brennt dann 12 Sekunden. Flametongue Weapon fügt jedem Treffer Feuerschaden hinzu; Searing Totem ist ein kleiner Turm, der auf einen nahen Feind schießt.",
    ["35c7293"] = "Enhancement ist die Spezialisierung, die wir für Quests empfehlen. Sie hat ihre Schwächen: Eine schlechte Waffe senkt den Schaden stark, die Manakosten am Anfang wiegen schwer und gegen viele Feinde gleichzeitig tut sie sich schwer.",
    ["028a6b7"] = "Stormstrike trifft sofort mit dem vollen Waffenschaden alle 8 Sekunden, und das Ziel erleidet 20% mehr von deinem nächsten Lightning Bolt, Chain Lightning oder Earth Shock.",
    ["a94041d"] = "Stormstrike jedes Mal, wenn es bereit ist, und direkt danach Earth Shock (der Stormstrike-Treffer macht den Schock stärker). Rockbiter Weapon immer auf der Waffe und Lightning Shield auf dir. Vor dem Pull Strength of Earth und Mana Spring und, wenn das Mana es zulässt, Searing Totem oder Magma Totem. Eröffne mit Lightning Bolt Rang 1 (der billigste), dann machen die normalen Treffer den Rest. Fire Nova nur, wenn die Monster in Reichweite deines Feuertotems sind und du noch Mana hast. Nach dem Kill Healing Wave, und trink, wenn das Mana knapp ist.",
    ["18a8896"] = "Windfury Weapon auf der Waffe statt Rockbiter: Jeder Treffer hat 20% Chance, zwei zusätzliche Angriffe zu geben, es ist das große Stück von Enhancement. Wenn ein Ausweichen oder Parieren Stormstrike zurücksetzt, drücke es sofort erneut. Windfury Totem, mit Grounding Totem an seiner Stelle gegen Zauberwirker.",
    ["f3777c4"] = "Maelstrom Weapon: Deine Treffer sammeln bis zu 5 Aufladungen, und jede Aufladung macht den nächsten Lightning Bolt schneller und billiger: Bei 5 Aufladungen wirke Lightning Bolt im höchsten Rang. Ab 46 ersetzt Water Shield das Lightning Shield (du kannst nur eines haben).",
    ["022a55d"] = "Für Enhancement zählt vor allem die Waffe: Ideal ist ein langsamer Zweihänder mit 3,3 bis 3,8 Geschwindigkeit. Dann Stärke und Angriffskraft, mit Intelligenz direkt dahinter, weil sie Mental Dexterity und das Mana speist.",
    ["4540d89"] = "Earthbound: Wenn du Earthbind Totem setzt, bleiben nahe Feinde 5 Sekunden lang festgehalten.",
    ["bcd1d77"] = "Vor dem Pull Mana Spring Totem und ein Feuertotem (Searing gegen ein Monster, Magma gegen mehrere), Lightning Shield auf dich. Eröffne an der Reichweitengrenze mit Lightning Bolt, wirke Flame Shock auf das Ziel und mach mit Lightning Bolt weiter. Bei drei oder mehr Monstern Fire Nova jedes Mal, wenn es bereit ist. Earth Shock unterbricht einen Zauberwirker und bringt ihn zu dir. Earthbind Totem, wenn sich Monster nähern. Heile und trink am Ende.",
    ["13a3832"] = "Gegen ein einzelnes Monster: Searing Totem, eröffne aus der Ferne mit Lightning Bolt, Flame Shock, mach mit Lightning Bolt weiter. Gegen drei oder mehr: Magma Totem, eröffne mit Chain Lightning, Flame Shock auf eines davon, dann Chain Lightning und Fire Nova bei jeder Abklingzeit mit Lightning Bolt dazwischen.",
    ["2c3ba7a"] = "Lightning Mastery (15 Sekunden, dann 3 Minuten): 15 Sekunden lang wird Lightning Bolt schneller gewirkt und Chain Lightning ignoriert seine Abklingzeit. Nutze es bei einem Elite oder einem großen Pull, sonst bei jeder Abklingzeit.",
    ["b56c9ed"] = "Water Shield ersetzt Lightning Shield auf dir.",
    ["4688073"] = "Für Elemental suche Zaubermacht, mit Intelligenz vor allem für das Mana. Ab Stufe 40 kannst du Kettenrüstung tragen.",
    ["b4ca62b"] = "Vor dem Pull Water Shield, Mana Spring Totem und die Totems, die die Gruppe nutzen kann. Während jemand Schaden nimmt, ist Healing Wave das Arbeitspferd. Lesser Healing Wave wird in 1,5 Sekunden gewirkt und heilt für das Mana weniger: Spar es für Momente auf, in denen Zeit zählt. Mana Tide Totem (12 Sekunden, 5 Minuten Abklingzeit), wenn die ganze Gruppe kein Mana mehr hat. Wenn niemand in Gefahr ist, füge Schaden hinzu: Lightning Bolt auf ein Ziel, Fire Nova auf eine Gruppe. Trink am Ende.",
    ["42937c0"] = "Nature's Swiftness (alle 3 Minuten): Dein nächster Naturzauber ist sofort wirksam, also eine sofortige Healing Wave für einen Freund, der gleich stirbt. Windfury Totem, wenn Spieler im Nahkampf sind.",
    ["9b2d19c"] = "Riptide: Heilung über Zeit mit 12 Sekunden Abklingzeit, und eine Chain Heal, die genau auf das Ziel von Riptide gewirkt wird, ist 25% stärker. Chain Heal heilt das Ziel und zwei weitere Verbündete, deckt also über die Gruppe verteilten Schaden ab.",
    ["a86408d"] = "Für Restoration suche Heilungsmacht, mit Intelligenz vor allem für das Mana. Ab Stufe 40 kannst du Kettenrüstung tragen.",
    ["c86a1be"] = "Voidwalker (Klassenquest), Drain Soul, Healthstone",
    ["40cb6b4"] = "Succubus und Incubus (Klassenquests), Demon Armor, Curse of the Elements, Rain of Fire, Ritual of Summoning",
    ["df7bfa2"] = "Felhunter (Klassenquest), Hellfire",
    ["19e5308"] = "Howl of Terror, Felsteed (Quest)",
    ["1c5b068"] = "Der Dämon geht zuerst rein, dann Bane of Agony und Corruption; nur die härtesten Monster bekommen Immolate, weil der Dämon sie hält. Die Reihenfolge zählt, weil Schaden Aufmerksamkeit zieht: Die ersten Ticks von Agony sind klein, also hält der Dämon das Monster, bis ein frisches Immolate hart genug trifft, damit es sich dir zuwendet. Halte Demon Skin aufrecht, überspringe DOTs auf einem fast toten Monster und erneuere Agony nicht, solange es noch Schaden macht. Bis du einen Zauberstab hast, erledigt Shadow Bolt die Arbeit; dann besorg dir einen Zauberstab: Jeder Schuss ist gespartes Mana für den nächsten Pull.",
    ["ea42414"] = "Drain Soul ist deine Hauptquelle für Soul Shards: Ein nicht triviales Monster, das an seinem Drain stirbt, gibt immer einen. Wenn du wenige hast, schließe deine Kills damit ab. Healthstone, Soul Stone und die Beschwörungen von Voidwalker, Succubus und Felhunter brauchen Splitter.",
    ["72f97d5"] = "Drain Life ändert, wie du den Bildschirm liest: Wenn die blaue Leiste niedrig ist und dein Leben gut ist, Life Tap; wenn dein Leben wirklich gesunken ist, Drain Life auf das Monster. So verschwindet fast die ganze Leerlaufzeit.",
    ["51205f3"] = "Demon Armor statt Demon Skin. Mit Ritual of Summoning holen du und zwei Gefährten ein Gruppenmitglied heran, das noch weit weg ist. Ein Fear gibt dir ein paar freie Sekunden für einen Verband.",
    ["9d83c05"] = "Wenn du allein spielst, ist Affliction die Wahl: Trefferchance und ein sofortiges Corruption kommen früh. Curse of the Elements kommt neben Agony. Ab 25 kann Nightfall durch den Schaden von Corruption, Drain Life oder Drain Soul auslösen, und der Shadow Bolt nach dem Proc hat keine Zauberzeit. Du kannst das Drain-Talent etwas vor 30 nehmen und dich in jedem Kampf auf Drain Life stützen.",
    ["04f03c2"] = "Siphon Life: ein Tick alle 3 Sekunden über 30 Sekunden, also bekommt ein Monster, das in 10 stirbt, nur ein Drittel. Spar es für lange Kämpfe auf.",
    ["703c37f"] = "Demonic Sacrifice: Du opferst den Felhunter und erhältst zwei Stunden lang alle 4 Sekunden 3% deines gesamten Lebens zurück; einen Dämon zu beschwören hebt es auf, also machst du ab hier Quests fast ohne Tier.",
    ["2dbcea6"] = "Wrack: Du kanalisierst 6 Sekunden lang, es macht Schattenschaden, und deine anderen Schatten-DOTs auf dem Ziel treffen währenddessen 10% stärker.",
    ["edb7e47"] = "Wähle Waffen mit Zaubermacht, weil du sie fast nie zum Zuschlagen nutzt. Am Anfang schlägt ein Zauberstab-Upgrade fast alle anderen; später kommt die Zaubermacht zuerst. Ausdauer ist zusätzliches Leben, das du mit Life Tap in Mana verwandelst, Intelligenz ein größerer Manavorrat, Willenskraft bringt bei jedem Life Tap mehr.",
    ["1c3a6a3"] = "Wenn du lieber dem Dämon bei der Arbeit zusiehst, Demonology: mit Demonic Brand ab 25. Ab 25 setzt Searing Pain eine Markierung auf das Ziel für 10 Sekunden, und höchstens die ersten sechs Treffer deines Dämons machen Zusatzschaden: Erneuere sie mit einem schnellen Searing Pain auf das, was der Dämon bekämpft, und fülle die Lücken mit DOTs und dem Zauberstab.",
    ["00d4a86"] = "Soul Link: 30% jedes direkten Treffers auf dich gehen an den Dämon, und ihr beide macht 3% mehr Schaden. Es geht verloren, wenn du den Dämon wechselst: Wirke es jedes Mal neu.",
    ["a3cee7a"] = "Demonic Pact: Das Opfer überlebt den Dämonenwechsel, es sei denn, du beschwörst genau den, den du geopfert hast. In einem Dungeon opfere den Imp (15% mehr Schattenschaden); bei Solo-Quests den Felhunter wegen seiner Heilungen, und kämpfe neben einem Voidwalker, Succubus oder Incubus. Ab 27 kannst du auch als Affliction leveln und die Spezialisierung wechseln: Du hast die Punkte für alle drei Ränge von Demonic Brand.",
    ["545f2c9"] = "Destruction ist ab 10 spielbar, wird aber bei 39 und 40 viel stärker und steht länger still beim Zaubern als die beiden anderen: Du kannst sie auch später wählen.",
    ["0b5d29c"] = "Shadowburn: ein Sofortschlag, der einen Shard kostet und ihn zurückgibt, wenn ein nicht triviales Ziel innerhalb von 8 Sekunden stirbt.",
    ["124afde"] = "Die Eröffnung ändert sich: Shadow Bolt aus maximaler Distanz und Immolate, während der Bolt noch fliegt. So kommt das Monster zu dir und nicht zum Dämon, also wähle Kämpfe, die du schnell beenden kannst. Shadowburn erledigt Monster; Conflagrate hebt man besser für das Ende deines Immolate auf.",
    ["07ea333"] = "Mit Shadow and Flame erhöht Conflagrate deinen Schattenschaden um 20% und Shadowburn deinen Feuerschaden um 20%; Conflagrate verbraucht Immolate nicht mehr und Shadowburn gibt den Shard immer zurück. Ab 39 gibt es keinen Grund, sie zurückzuhalten.",
    ["609f38c"] = "Incinerate macht 25% mehr gegen alles, was schon durch dein Immolate brennt.",
    ["a1d5005"] = "Defensive Stance, Taunt, Sunder Armor (Klassenquest), Bloodrage",
    ["b87bfb2"] = "Revenge, Demoralizing Shout, Tactical Mastery (beim Lehrer zu lernen)",
    ["a61955b"] = "Victory Rush, Cleave, Slam, Retaliation; du kannst zwei Waffen benutzen",
    ["323f468"] = "Berserker Stance, Berserker Rage, Intercept (Klassenquest)",
    ["b289adb"] = "Plattenrüstung und Reittier",
    ["2debde0"] = "Battle Shout vor dem Pull, Charge, Rend auf das, was lange lebt, dann lass die normalen Treffer Wut aufbauen. Heroic Strike nur mit Wut, die du nicht brauchst: Es ersetzt einen normalen Treffer und dieser Treffer gibt keine Wut. Bei mehreren Monstern Thunder Clap; gib keine Wut auf ein Monster aus, das gleich stirbt.",
    ["f98c5d6"] = "Bloodrage zwischen den Pulls: Es kostet etwas Leben und gibt sofort 10 Wut und 10 in 10 Sekunden. Beginne nie einen Kampf ohne Wut.",
    ["970305a"] = "Victory Rush jedes Mal, wenn es aufleuchtet: Nach einem Kill, der Erfahrung gibt, hast du 20 Sekunden, es macht Schaden und heilt dich um 10%, 30 Sekunden Abklingzeit und kostet keine Wut.",
    ["a60b4a3"] = "Ab 14 ist Revenge dein Hauptangriff: Nutze es jedes Mal, wenn es aufleuchtet (nach einem Block, einem Ausweichen oder einem Parieren). Wechsle zu Schild und Einhandwaffe. Thunder Clap und Demoralizing Shout auf Gruppen.",
    ["41fd2f0"] = "Charge, dann bleib in Defensive Stance. Halte Shield Block gegen alles, was dich im Nahkampf trifft, und überspringe Shield Block gegen Zauberwirker. Revenge jedes Mal, wenn es aufleuchtet; Rend und ein paar Sunder Armor auf Monstern, die lange leben; Thunder Clap und Demoralizing Shout auf Gruppen.",
    ["b604238"] = "Mit Vanguard kannst du aus Defensive Stance Charge nutzen: Du kannst einen Pull eröffnen, ohne die Haltung zu wechseln, wenn du außerhalb des Kampfes bist.",
    ["c9e7c22"] = "Shield Wall: 60% weniger Schaden für 12 Sekunden, für Pulls, die schlecht laufen.",
    ["3f0c2f4"] = "Shield Slam ist der stärkste Treffer (der Schaden wächst mit deinem Blockwert): Nutze ihn zuerst und Revenge direkt danach. Wenn du wenig Wut hast, zuerst Revenge, es kostet weniger.",
    ["846367b"] = "Protection will vor allem Stärke (jeder Punkt gibt 2 Angriffskraft und Blockwert). Nimm für die Waffe den besten DPS: Revenge und Shield Slam hängen nicht von der Waffe ab. Beweglichkeit zählt weniger: Sie gibt kritische Treffer, Ausweichen und Rüstung, aber keine Angriffskraft.",
    ["fabdcb6"] = "Zuerst Rend, dann Overpower jedes Mal, wenn es aufleuchtet (nach einem Ausweichen des Ziels).",
    ["f29cf52"] = "Rend, dann Overpower, wenn es aufleuchtet. Ab 20 Slam direkt nach einem Treffer.",
    ["60998aa"] = "Sweeping Strikes: Deine nächsten fünf Treffer treffen auch einen zweiten nahen Feind, ein großer Sprung. Beginne an einem Monster, solange du Wut übrig hast, dann hol ein zweites Monster und nutze Sweeping Strikes und Cleave auf beide.",
    ["efc030d"] = "Mit Bloodthrill haben die Haupthandtreffer, wenn Rend auf dem Ziel ist, 20% Chance, Overpower auszulösen: Rend bleibt bis 60 in der Rotation.",
    ["98a8fec"] = "Mortal Strike ist dein neuer Hauptangriff.",
    ["7caf705"] = "Die Waffe zählt mehr als alles andere: Suche den höchsten DPS, und für Arms einen langsamen Zweihänder (jeder Treffer und Mortal Strike und Slam machen mehr Schaden). Beim Rest zuerst Trefferwertung (Hit, denn ein verfehlter Treffer gibt weder Schaden noch Wut), dann Stärke und kritische Treffer. Beweglichkeit gibt kritische Treffer und Ausweichen, aber keine Angriffskraft.",
    ["ce62f29"] = "Rend auf Monster, die lange leben, Overpower, wenn das Ziel ausweicht. Wenn ein zweites Monster neben dem Ziel steht, gib die zusätzliche Wut für Cleave aus. Wähle eine schnelle Nebenhand: mehr Treffer, mehr Wut.",
    ["1879df1"] = "Death Wish: 30 Sekunden lang machst du 20% mehr physischen Schaden und kannst nicht verängstigt werden, erleidest aber 5% mehr Schaden. Reckless Swings (31): Es kostet etwas Leben und die nächsten vier Treffer geben jeweils 5 Wut mehr.",
    ["0d27ce4"] = "Mit Whirlwind (Stufe 36) ist es deine Haupttaste, sogar gegen ein einzelnes Monster: Die Abklingzeit sinkt auf 8 Sekunden und es trifft den nächsten mit 30% mehr Schaden.",
    ["308a3c5"] = "Bloodthirst jedes Mal, wenn Whirlwind auf Abklingzeit ist. Ab 50 hast du Recklessness.",
    ["2d76abd"] = "Die Waffe zählt mehr als alles andere: Suche den höchsten DPS. Für die Nebenhand eine schnelle (mehr Treffer, mehr Wut). Beim Rest zuerst Trefferwertung (Hit), dann Stärke und kritische Treffer. Beweglichkeit gibt kritische Treffer und Ausweichen, aber keine Angriffskraft.",
}
